:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --primary-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --focus: #f5c542;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 640px;
  background: var(--card-bg);
  border: 3px solid var(--border);
  border-radius: 0;
  padding: 24px;
  box-shadow: 6px 6px 0 var(--border);
}

.header {
  margin-bottom: 20px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--primary);
  line-height: 1.2;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 1rem;
  color: var(--muted);
}

.label {
  display: block;
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--text);
}

.textarea {
  width: 100%;
  min-height: 160px;
  padding: 12px;
  font-family: inherit;
  font-size: 1rem;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  resize: vertical;
  outline: none;
  transition: border-color 0.15s ease;
}

.textarea::placeholder {
  color: var(--muted);
  opacity: 0.7;
}

.textarea:hover {
  border-color: var(--primary);
}

.textarea:focus-visible {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(245, 197, 66, 0.3);
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin: 20px 0;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 12px 4px;
  background: var(--bg);
  border: 3px solid var(--border);
  text-align: center;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  line-height: 1.2;
  word-break: break-word;
}

.stat-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--muted);
  margin-top: 4px;
}

.button {
  display: block;
  width: 100%;
  padding: 14px 24px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #fff;
  background: var(--primary);
  border: 3px solid var(--border);
  border-radius: 0;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.05s ease, box-shadow 0.05s ease;
}

.button:hover {
  background: var(--primary-hover);
}

.button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.button:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
    box-shadow: 4px 4px 0 var(--border);
  }

  h1 {
    font-size: 1.4rem;
  }

  .stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .stat-value {
    font-size: 1.25rem;
  }
}

const textInput = document.getElementById('text-input');
const wordCountEl = document.getElementById('word-count');
const charCountEl = document.getElementById('char-count');
const sentenceCountEl = document.getElementById('sentence-count');
const readingTimeEl = document.getElementById('reading-time');
const clearBtn = document.getElementById('clear-btn');

const WORDS_PER_MINUTE = 200;

function countWords(text) {
  const trimmed = text.trim();
  if (!trimmed) return 0;
  return trimmed.split(/\s+/).length;
}

function countSentences(text) {
  const trimmed = text.trim();
  if (!trimmed) return 0;
  const matches = trimmed.match(/[^.!?]+[.!?]+/g);
  if (!matches) return 1;
  const remainder = trimmed.replace(/[^.!?]+[.!?]+/g, '').trim();
  return matches.length + (remainder ? 1 : 0);
}

function formatReadingTime(words) {
  if (words === 0) return '0 min';
  const minutes = words / WORDS_PER_MINUTE;
  if (minutes < 1) return '<1 min';
  return Math.ceil(minutes) + ' min';
}

function updateStats() {
  const text = textInput.value;
  const words = countWords(text);
  const chars = text.length;
  const sentences = countSentences(text);
  const readingTime = formatReadingTime(words);

  wordCountEl.textContent = words;
  charCountEl.textContent = chars;
  sentenceCountEl.textContent = sentences;
  readingTimeEl.textContent = readingTime;
}

textInput.addEventListener('input', updateStats);

clearBtn.addEventListener('click', function () {
  textInput.value = '';
  updateStats();
  textInput.focus();
});

updateStats();
